def calculate_campaign_yield(df):
    df['tag'] = df['campaign_id'].str.replace('[.]', '_', regex=True)
    rows = []
    for tag in df['tag'].unique():
        subset = df[df['tag'] == tag]
        val = subset['conversions'].sum() / subset['clicks'].sum() * 100
        rows.append({'tag': tag, 'yield': val})
    return pd.DataFrame(rows)

