    matrix = np.vstack(coords)
    rows = [{'metric': 'sum', 'val': matrix[0, 0]}]
    for i in range(1, matrix.shape[0]):
        rows.append({'metric': f'adj_{i}', 'val': matrix[i, 0]})
    return pd.DataFrame(rows)

