def gen(rng):
    n = rng.randint(5, 12)
    student_ids = [rng.randint(1000, 9999) for _ in range(n)]
    scores = [float(rng.randint(60, 100)) if rng.random() > 0.3 else None for _ in range(n)]

    # Ensure at least one None exists and it's not the first element for ffill to work
    if None not in scores:
        scores[rng.randint(1, n - 1)] = None
    elif scores[0] is None:
        scores[0] = float(rng.randint(60, 100))

    priority_students = rng.sample(student_ids, k=rng.randint(1, n))

    return {
        "df": {"__df__": {"StudentID": student_ids, "Score": scores}},
        "priority_students": priority_students
    }

